"use strict";
import { AnimatePresence, motion } from "framer-motion";
import { useState } from "react";
import styled from "styled-components";
import { Flex, Separator, Text, styled as UiStyled } from "ui/src";
import { Check, Plus } from "ui/src/components/icons";
import { useFilters } from "../contexts/FilterContext";
const Button = styled.button`
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 10px 10px;
  background-color: transparent;
  border: none;
  cursor: pointer;
  hover {
    color: red;
  }
`;
const TextCotainer = UiStyled(Text, {
  variant: "body3",
  color: "$neutral1",
  cursor: "pointer",
  transition: "color 0.2s ease-in-out",
  hoverStyle: {
    color: "$neutral2"
  }
});
const Checkmark = function() {
  return <Check color={"$greenVibrant"} size={"$icon.12"} />;
};
const PlusSign = function() {
  return <Plus color={"$neutral1"} size={"$icon.12"} />;
};
const FIlterContainer = UiStyled(Flex, {
  row: true,
  flexWrap: "nowrap",
  borderStyle: "solid",
  borderWidth: 1,
  borderColor: "$surface3",
  borderRadius: "$rounded12"
});
export default function FilterPoolsButtons() {
  const { filters, setFilters } = useFilters();
  const [basicButtonToggle, setBasicButtonToggle] = useState(false);
  const handleBasicConcentratedButton = function(type, value) {
    if (type === "Basic") {
      setBasicButtonToggle(value);
    } else {
      setBasicButtonToggle(false);
    }
    setTimeout(() => {
      if (type === "Basic") {
        setFilters({
          ...filters,
          Basic: value,
          Concentrated: value ? false : filters.Concentrated
        });
      } else {
        setFilters({
          ...filters,
          Concentrated: value,
          Basic: value ? false : filters.Basic
        });
      }
    }, 250);
  };
  const GenerateFilterButton = function({
    type,
    divider
  }) {
    const handleFilter = function(value) {
      switch (type) {
        case "Basic":
          handleBasicConcentratedButton(type, value);
          break;
        case "Concentrated":
          handleBasicConcentratedButton(type, value);
          break;
        case "Stable":
          setFilters({
            ...filters,
            Stable: value,
            Volatile: value ? false : filters.Volatile
          });
          break;
        case "Volatile":
          setFilters({
            ...filters,
            Volatile: value,
            Stable: value ? false : filters.Stable
          });
          break;
        case "Gauge":
          setFilters({
            ...filters,
            Gauge: value
          });
          break;
      }
    };
    return <>
        {divider && <Separator vertical minHeight={"100%"} />}
        <Button onClick={() => handleFilter(!filters[type])}>
          <TextCotainer>{type}</TextCotainer> {filters[type] ? <Checkmark /> : <PlusSign />}
        </Button>
      </>;
  };
  return <Flex
    width={"100%"}
    flex={1}
    $platform-web={{
      overflowX: "auto"
    }}
  >
      <Flex row gap={"$spacing12"} pb={0} $lg={{ pb: "$spacing16" }} width={basicButtonToggle ? 500 : "auto"}>
        <FIlterContainer>
          <GenerateFilterButton type={"Basic"} />
          <GenerateFilterButton type={"Concentrated"} divider />
        </FIlterContainer>

        {
    /* <FIlterContainer display={filters.Basic ? 'flex' : 'none'}>
      <GenerateFilterButton type={'Stable'} />
      <GenerateFilterButton type={'Volatile'} divider />
    </FIlterContainer> */
  }

        <AnimatePresence>
          {basicButtonToggle && <motion.div
    style={{ display: "flex", overflow: "hidden", whiteSpace: "nowrap" }}
    initial={{ width: 0, opacity: 0 }}
    animate={{ width: "auto", opacity: 1 }}
    exit={{ width: 0, opacity: 0 }}
    transition={{ duration: 0.15, ease: "easeInOut" }}
  >
              <FIlterContainer>
                <GenerateFilterButton type={"Stable"} />
                <GenerateFilterButton type={"Volatile"} divider />
              </FIlterContainer>
            </motion.div>}
        </AnimatePresence>

        <FIlterContainer>
          <GenerateFilterButton type={"Gauge"} />
        </FIlterContainer>
      </Flex>
    </Flex>;
}
